python3 << 'EOF'
# Refine: make all intended pairs GC-strong, and ensure spurious registers are mismatched
t = '..(.(..((((((....))))))..).)......((((..(((.(((((((((....)))))....)))))))))))..((((((((....))))))))..'
n = len(t)
stack=[]; pairs={}
for i,c in enumerate(t):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
pl = sorted([(i,pairs[i]) for i in pairs if i<pairs[i]])

# Assign GC/CG alternating to all pairs
seq=['A']*n
for k,(i,j) in enumerate(pl):
    if k%2==0:
        seq[i],seq[j]='G','C'
    else:
        seq[i],seq[j]='C','G'

# unpaired -> A (but for loops near stems use U to reduce stacking)
for i in range(n):
    if t[i]=='.':
        seq[i]='A'

sequence=''.join(seq)
print(sequence)
print(len(sequence))
EOF

